import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { PaymentMethods } from 'shared-code-lib';
import { PaymentMethodConfigurations } from '../../../../blocks/InterFAX/Models/payment-methods';

@Component({
  selector: 'app-paypal-payment-method',
  templateUrl: './paypal-payment-method.component.html',
  styleUrls: ['./paypal-payment-method.component.scss'],
})
export class PayPalPaymentMethodComponent implements OnInit {
  @Input() currentPaymentMeans: string;
  @Input() showSetupMessage: boolean = true;
  @Input() showHeader: boolean = true;
  @Output() onCancel = new EventEmitter<void>();
  @Output() onStartSetup = new EventEmitter<PaymentMethodConfigurations>();

  color: string;
  icon: string;
  configMessage: string;

  constructor() {}

  ngOnInit(): void {
    this.color = this.currentPaymentMeans === PaymentMethods.PayPal ? 'darkgreen' : 'darkred';
    this.icon = this.currentPaymentMeans === PaymentMethods.PayPal ? 'fa-check' : 'fa-times';
    this.configMessage = `fax-account-properties.payment-method-paypal-${
      this.currentPaymentMeans === PaymentMethods.PayPal ? 'configured' : 'not-configured'
    }`;
  }

  onCancelClicked = () => this.onCancel.emit();

  startSetup = () => {
    const config = new PaymentMethodConfigurations(PaymentMethods.PayPal);

    this.onStartSetup.emit(config);
  };
}
