import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { CharactersValidator, FieldDefinition, FixedDataSource, IFieldOptions, MetaDataType } from 'shared-code-lib';
import { CountryContext, CreditCard } from '../../../../blocks/InterFAX/Models/admin';
import { CreditCardType, detectCreditCardType } from '../../../../blocks/models/credit-card-type';

@Component({
  selector: 'app-credit-card',
  templateUrl: './credit-card.component.html',
  styleUrls: ['./credit-card.component.scss'],
})
export class CreditCardComponent implements OnInit {
  @Input() creditCard: CreditCard;
  @Input() enabled: boolean;
  @Input() countryContext: CountryContext;
  @Output() cardDetailsChanged = new EventEmitter();

  fieldNumber: FieldDefinition;
  fieldName: FieldDefinition;
  fieldType: FieldDefinition;
  fieldExpirationMonth: FieldDefinition;
  fieldExpirationYear: FieldDefinition;
  fieldCVV: FieldDefinition;
  fieldId: FieldDefinition;

  constructor(
    private translateService: TranslateService,
    public validator: CharactersValidator
  ) {}

  ngOnInit(): void {
    this.createFields();
  }

  getOptionsFor = (start: number, end: number): Array<IFieldOptions> => {
    const options = new Array<IFieldOptions>();

    options.push({ name: this.translateService.instant('fax-account-properties.select-value'), value: '' });

    for (let index = start; index <= end; index++) {
      options.push({ name: index.toString(), value: index.toString() });
    }

    return options;
  };

  getCardTypeOptions = (): Array<IFieldOptions> => {
    const options = new Array<IFieldOptions>();

    options.push({ name: this.translateService.instant('fax-account-properties.select-value'), value: '' });

    for (const card of this.countryContext.allowedCreditCards) {
      const translatedName = this.translateService.instant(`fax-account-properties.cc-type-${card.toLowerCase()}`);
      options.push({
        name: translatedName == `fax-account-properties.cc-type-${card.toLowerCase()}` ? card : translatedName,
        value: card,
      });
    }

    return options;
  };

  createFields = (): void => {
    const currentYear = new Date().getFullYear();
    const cardTypes = new FixedDataSource(this.getCardTypeOptions());
    const expirationMonths = new FixedDataSource(this.getOptionsFor(1, 12));
    const expirationYears = new FixedDataSource(this.getOptionsFor(currentYear, currentYear + 10));

    this.fieldNumber = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('fax-account-properties.cc-number'),
      placeholder: '',
      required: true,
    });

    this.fieldName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('fax-account-properties.cc-name'),
      placeholder: '',
      required: true,
    });

    this.fieldType = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('fax-account-properties.cc-type'),
      placeholder: '',
      required: true,
      datasource: cardTypes,
    });

    this.fieldExpirationMonth = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('fax-account-properties.cc-expiration-month'),
      placeholder: '',
      required: true,
      datasource: expirationMonths,
    });

    this.fieldExpirationYear = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('fax-account-properties.cc-expiration-year'),
      placeholder: '',
      required: true,
      datasource: expirationYears,
    });

    this.fieldCVV = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('fax-account-properties.cc-cvv'),
      placeholder: '',
      required: true,
    });

    this.fieldId = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('fax-account-properties.cc-id'),
      placeholder: '',
      required: true,
    });
  };

  fieldChanged = (): void => {
    this.cardDetailsChanged.emit();
  };

  mapCreditCardType = (value: string): CreditCardType => {
    return detectCreditCardType(value);
  };

  removeUnnecessaryZerosAndDigits = (value: string): string => {
    if (!value) return '';
    return Number(value).toString();
  };
}
