import { Component, EventEmitter, Output } from '@angular/core';
import { PaymentMethods } from 'shared-code-lib';
import { PaymentMethodConfigurations } from '../../../../blocks/InterFAX/Models/payment-methods';

@Component({
  selector: 'app-direct-debit',
  templateUrl: './direct-debit.component.html',
  styleUrls: ['./direct-debit.component.scss'],
})
export class DirectDebitComponent {
  @Output() onStartSetup = new EventEmitter<PaymentMethodConfigurations>();

  constructor() {}	

  startSetup = (): void => {
    const config = new PaymentMethodConfigurations(PaymentMethods.DD);

    config.configurations.push({ key: 'PaymentGWType', value: 'GoCardless' });
    config.configurations.push({ key: 'Description', value: 'Payment Method Setup' });
    this.onStartSetup.emit(config);
  };

}
