import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import {
  CharactersValidator,
  FieldDefinition,
  FixedDataSource,
  IFieldDataSource,
  IFieldOptions,
  MetaDataType,
  PaymentMethods,
} from 'shared-code-lib';
import {
  Account,
  AccountRegistrationDetails,
  Address,
  CountryContext,
  CreditCard,
} from '../../../../blocks/InterFAX/Models/admin';

import { CreditCardType, detectCreditCardType } from '../../../../blocks/models/credit-card-type';

@Component({
  selector: 'app-credit-card-payment-method',
  templateUrl: './credit-card-payment-method.component.html',
  styleUrls: ['./credit-card-payment-method.component.scss'],
})
export class CreditCardPaymentMethodComponent implements OnInit {
  @Input() currentPaymentMeans: string;
  @Input() account: Account;

  _accountRegistrationDetails: AccountRegistrationDetails;
  @Input() set accountRegistrationDetails(val: AccountRegistrationDetails) {
    this._accountRegistrationDetails = val;

    const cardTypes = this.getCardTypes(val.country);

    this.createFields(new FixedDataSource(cardTypes));
  }
  get accountRegistrationDetails(): AccountRegistrationDetails {
    return this._accountRegistrationDetails;
  }

  _creditCard: CreditCard;
  @Input() set creditCard(val: CreditCard) {
    this._creditCard = new CreditCard(val);

    this._creditCard.changed = true;
    this.creditCardChange.next(this._creditCard);
  }
  get creditCard() {
    return this._creditCard;
  }
  @Output() creditCardChange = new EventEmitter<CreditCard>();

  _address: Address;
  @Input() set address(val: Address) {
    this._address = new Address(val);
    this.addressChange.next(this._address);
  }
  get address() {
    return this._address;
  }

  @Output() addressChange = new EventEmitter<Address>();
  @Output() onCancel = new EventEmitter<void>();
  @Output() onToggleEditCC = new EventEmitter(false);

  fieldName: FieldDefinition;
  fieldNumber: FieldDefinition;
  fieldType: FieldDefinition;
  fieldExpMonth: FieldDefinition;
  fieldExpYear: FieldDefinition;
  fieldCvv: FieldDefinition;
  fieldId: FieldDefinition;
  fieldAddress1: FieldDefinition;
  fieldAddress2: FieldDefinition;
  fieldCity: FieldDefinition;
  fieldState: FieldDefinition;
  fieldPostalCode: FieldDefinition;
  fieldCountry: FieldDefinition;
  fieldPhoneNumber: FieldDefinition;

  showEditView: boolean = false;

  constructor(
    private translate: TranslateService,
    public validator: CharactersValidator
  ) {}

  ngOnInit(): void {
    if (!this.creditCard.valid || this.currentPaymentMeans !== PaymentMethods.CC) {
      this.toggleEditView(true);
    }

    if (this.currentPaymentMeans !== PaymentMethods.CC) {
      this.creditCard = new CreditCard();
    }
  }

  private getCardTypes = (context: CountryContext) => {
    const options = new Array<IFieldOptions>();

    options.push({ name: this.translate.instant('fax-account-properties.select-value'), value: '' });

    for (const card of context.allowedCreditCards) {
      const translatedName = this.translate.instant(`fax-account-properties.cc-type-${card.toLowerCase()}`);
      options.push({
        name: translatedName == `fax-account-properties.cc-type-${card.toLowerCase()}` ? card : translatedName,
        value: card,
      });
    }

    return options;
  };

  createFields = (cardTypes: IFieldDataSource = null) => {
    const currentYear = new Date().getFullYear();
    const expirationMonths = new FixedDataSource(this.getOptionsFor(1, 12));
    const expirationYears = new FixedDataSource(this.getOptionsFor(currentYear, currentYear + 10));

    this.fieldName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('fax-account-properties.cc-name'),
      placeholder: '',
      required: true,
    });
    this.fieldNumber = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('fax-account-properties.cc-number'),
      placeholder: '',
      required: true,
    });
    this.fieldType = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translate.instant('fax-account-properties.cc-type'),
      placeholder: '',
      required: true,
      datasource: cardTypes,
    });
    this.fieldExpMonth = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translate.instant('fax-account-properties.cc-expiration-month'),
      placeholder: '',
      required: true,
      datasource: expirationMonths,
    });
    this.fieldExpYear = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translate.instant('fax-account-properties.cc-expiration-year'),
      placeholder: '',
      required: true,
      datasource: expirationYears,
    });
    this.fieldCvv = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('fax-account-properties.cc-cvv'),
      placeholder: '',
      required: true,
    });
    this.fieldId = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('fax-account-properties.cc-id'),
      placeholder: '',
      required: true,
    });
    this.fieldAddress1 = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('fax-account-properties.address1'),
      placeholder: '',
      required: true,
    });
    this.fieldAddress2 = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('fax-account-properties.address2'),
      placeholder: '',
    });
    this.fieldCity = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('fax-account-properties.city'),
      placeholder: '',
      required: true,
    });
    this.fieldState = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('fax-account-properties.state'),
      placeholder: '',
    });
    this.fieldPostalCode = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('fax-account-properties.postal-code'),
      placeholder: '',
      required: true,
    });
    this.fieldCountry = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('fax-account-properties.country'),
      placeholder: '',
      required: true,
    });
    this.fieldPhoneNumber = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('contact-list.phoneNumber'),
      placeholder: this.translate.instant('contact-list.phoneNumber-placeholder'),
      required: true,
    });
  };

  private getOptionsFor = (start: number, end: number): Array<IFieldOptions> => {
    const options = new Array<IFieldOptions>();

    options.push({ name: this.translate.instant('fax-account-properties.select-value'), value: '' });

    for (let index = start; index <= end; index++) {
      options.push({ name: index.toString(), value: index.toString() });
    }

    return options;
  };

  onUpdateClicked = () => {
    this.toggleEditView(true);
  };

  onCancelClicked = () => {
    this.toggleEditView(false);
    this.onCancel.emit();
  };

  toggleEditView(show: boolean) {
    this.showEditView = show;
    this.onToggleEditCC.emit(this.showEditView);
  }

  mapCreditCardType = (value: string): CreditCardType => {
    return detectCreditCardType(value);
  };

  removeUnnecessaryZerosAndDigits = (value: string): string => {
    if (!value) return '';
    return Number(value).toString();
  };
}
