import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { DirectDebitComponent } from '../direct-debit/direct-debit.component';
import { PaymentMethods } from 'shared-code-lib';

@Component({
  selector: 'app-direct-debit-payment-method',
  templateUrl: './direct-debit-payment-method.component.html',
  styleUrls: ['./direct-debit-payment-method.component.scss'],
})
export class DirectDebitPaymentMethodComponent extends DirectDebitComponent implements OnInit {
  @Input() isDirectDebitConfigured = false;
  @Input() currentPaymentMeans: string;
  @Output() onCancel = new EventEmitter<void>();

  ngOnInit(): void {
    if (this.currentPaymentMeans !== PaymentMethods.DD) this.isDirectDebitConfigured = false;
  }

  onCancelClicked = () => this.onCancel.emit();
}
